import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class HashtagCollector {

    private static final Pattern TAG = Pattern.compile("#([A-Za-z][A-Za-z0-9_]*)");

    public static List<String> hashtags(String text) {
        List<String> found = new ArrayList<>();
        if (text == null) {
            return found;
        }
        Matcher m = TAG.matcher(text);
        while (m.find()) {
            found.add(m.group(1).toLowerCase());
        }
        return found;
    }

    public static int countUnique(String text) {
        Set<String> distinct = new HashSet<>(hashtags(text));
        return distinct.size();
    }
}
